// ---------- generic approach structures under the app's elevated deck lines (exported runs [t, l, surface]) ----------
const WIDS = [[26,13],[6.5,6.5],[20,11],[6.5,6.5],[15,10],[6,6],[12,8],[5.5,5.5],[9.5,7],[5,5],[7,5.5],[4.5,4],[2.5,2.5],[60,60],[23,23],[4,4],[3,3],[4,4],[12,12]];
