    const d1 = [q[0] - p[0], q[1] - p[1]], d2 = [s[2] - s[0], s[3] - s[1]], den = d1[0]*d2[1] - d1[1]*d2[0]; if (Math.abs(den) < 1e-9) continue;
    const u = ((s[0] - p[0])*d2[1] - (s[1] - p[1])*d2[0])/den, v = ((s[0] - p[0])*d1[1] - (s[1] - p[1])*d1[0])/den;
